0deg,#164d45,#287b6d);color:#fff}.proposal-modal .modal-header small{color:#f2d187;font-weight:850;letter-spacing:.1em}.proposal-modal h2{margin:4px 0 0;font-size:1.25rem;font-weight:850}.proposal-modal .modal-body{padding:25px;background:#f6fbfa}.proposal-summary{padding:18px;margin-bottom:18px;border-left:5px solid #c59e5b;border-radius:13px;background:#fff}.proposal-summary h3{margin:0 0 5px;color:#274954;font-size:1.2rem;font-weight:850}.proposal-summary p{margin:0;color:#6e8187}.proposal-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.proposal-field{padding:12px 14px;border:1px solid #e0ece8;border-radius:10px;background:#fff}.proposal-field small{display:block;margin-bottom:4px;color:#789096;font-size:.68rem;font-weight:850;text-transform:uppercase}.proposal-field strong{color:#294a56;font-size:.86rem}.proposal-section{margin:20px 0 9px;color:#30515c;font-size:.94rem;font-weight:850}.proposal-docs{display:flex;flex-wrap:wrap;gap:8px}.proposal-docs a{padding:8px 10px;border:1px solid #c7ddd8;border-radius:8px;background:#fff;color:#1c746b;font-size:.78rem;font-weight:800;text-decoration:none}.proposal-photos{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.proposal-photo{overflow:hidden;border:1px solid #e0ebe8;border-radius:10px;background:#fff}.proposal-photo small{display:block;padding:8px 10px;color:#506a70;font-weight:800}.proposal-photo img{width:100%;height:150px;object-fit:cover}@media(max-width:991px){.proposal-layout{grid-template-columns:1fr}.proposal-panel{height:520px}#proposalMap{min-height:440px}}@media(max-width:576px){.proposal-hero{align-items:flex-start;padding:29px;flex-direction:column}.proposal-grid,.proposal-photos{grid-template-columns:1fr}.proposal-panel{height:480px}}</style>
<script>document.addEventListener('DOMContentLoaded',()=>{const records=@json($details),items=@json($proposalMapItems),modal=bootstrap.Modal.getOrCreateInstance(document.querySelector('#proposalDetailModal')),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));const show=d=>{if(!d)return;const field=([l,v])=>`<div class="proposal-field"><small>${l}</small><strong>${esc(v||'-')}</strong></div>`;const fields=[['Tahun Usulan',d.year],['NIK',d.national_id],['Nomor KK',d.family_card_number],['DTSEN Backlog',d.backlog],['DTSEN Desil',d.decile],['Kabupaten/Kota',d.regency],['Kecamatan',d.district],['Desa/Kelurahan',d.village],['Alamat',d.address],['Kepemilikan Lahan',d.land],['Koordinat',d.coordinates],['Status',{'submitted':'Diajukan','verified':'Terverifikasi','approved':'Disetujui','rejected':'Ditolak'}[d.status]]];const docs=Object.entries(d.documents||{}).map(([l,u])=>`<a href="${esc(u)}" target="_blank" rel="noopener"><i class="fas fa-file-arrow-down me-1"></i>${esc(l)}</a>`).join('')||'<span class="text-secondary small">Tidak ada dokumen.</span>';const photos=Object.entries(d.photos||{}).map(([l,u])=>`<a class="proposal-photo" href="${esc(u)}" target="_blank"><small>${esc(l)}</small><img src="${esc(u)}" alt="${esc(l)}"></a>`).join('')||'<p class="text-secondary small">Tidak ada dokumentasi foto.</p>';document.querySelector('#proposalDetailBody').innerHTML=`<section class="proposal-summary"><h3>${esc(d.name)}</h3><p><i class="fas fa-location-dot me-2"></i>${esc([d.village,d.regency].filter(Boolean).join(', ')||'-')}</p></section><div class="proposal-grid">${fields.map(field).join('')}</div>${d.description?`<h4 class="proposal-section">Uraian Usulan</h4><div class="proposal-summary">${esc(d.description)}</div>`:''}<h4 class="proposal-section">Dokumen Pendukung</h4><div class="proposal-docs">${docs}</div><h4 class="proposal-section">Dokumentasi Rumah</h4><div class="proposal-photos">${photos}</div>`;modal.show()};document.querySelectorAll('.js-proposal-detail').forEach(b=>b.addEventListener('click',()=>show(records[b.dataset.id])));const map=L.map('proposalMap').setView([-3.7,128.2],7);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap',maxZoom:19}).addTo(map);const icon=L.divIcon({className:'proposal-marker',html:'<i class="fas fa-house"></i>',iconSize:[38,38],iconAnchor:[19,34]});const markers=items.map(item=>{const marker=L.marker([item.lat,item.lng],{icon}).addTo(map);marker.on('click',()=>show(records[item.id]));return{item,marker}});if(markers.length)map.fitBounds(L.featureGroup(markers.map(x=>x.marker)).getBounds().pad(.15));const list=[...document.querySelectorAll('.proposal-item')],year=document.querySelector('#proposalYear'),regency=document.querySelector('#proposalRegency'),search=document.querySelector('#proposalSearch'),apply=()=>{const y=year.value,r=regency.value.toLowerCase(),s=search.value.toLowerCase().trim(),ids=new Set();let count=0;list.forEach(el=>{const show=(!y||el.dataset.year===y)&&(!r||el.dataset.regency===r)&&(!s||el.dataset.search.includes(s));el.hidden=!show;if(show){count++;ids.add(+el.querySelector('.js-proposal-detail').dataset.id)}});let points=0;markers.forEach(({item,marker})=>{if(ids.has(+item.id)){marker.addTo(map);points++}else marker.remove()});document.querySelector('#proposalListCount').textContent=count;document.querySelector('#proposalMapCount').textContent=points+' titik'};[year,regency,search].forEach(el=>el.addEventListener(el===search?'input':'change',apply))})</script>
